def conservar_periodos(apps, schema_editor):
    Abono = apps.get_model("patrimonio", "AbonoCuentaPorCobrar")
    Partida = apps.get_model("patrimonio", "PartidaRevisionCobro")
    using = schema_editor.connection.alias
    for abono in Abono.objects.using(using).all().iterator():
        aplicado = Partida.objects.using(using).filter(
            abono_id=abono.pk, resuelta_en__isnull=False,
            decision__in=["APLICAR", "CONCILIAR", "RESPALDO"],
        ).order_by("-resuelta_en__periodo", "-resuelta_en__revision").first()
        Abono.objects.using(using).filter(pk=abono.pk).update(
            periodo=aplicado.periodo if aplicado else abono.fecha.replace(day=1),
        )
    # Sólo recupera como entrada explícita los registros manuales. Una
    # sugerencia bancaria o Neat antigua sigue esperando su revisión.
    Partida.objects.using(using).filter(
        resuelta_en__isnull=True, movimiento__isnull=True, evento_externo__isnull=True,
    ).filter(models.Q(tipo__in=["EDITAR", "AJUSTE"]) | models.Q(clave__startswith="manual:")).update(
        registrada_por_usuario=True,
    )


